<?php if($bundle): ?>
<?php if($step<8): $defs=SimpleMartyrForm::definitions($db,$step);$values=SimpleMartyrForm::values($bundle,$step,$db);if($old)$values=array_replace($values,$old['data']??[]);$militaryVisible=false;foreach($terms as $term)if(!empty(Protocol::decode($term['metadata'])['military_trigger'])&&in_array((string)$term['id'],array_map('strval',array_merge((array)($values['employment_state']??[]),(array)($values['occupations']??[]))),true))$militaryVisible=true; ?>
<section class="panel simple-martyr-section"><h2><?= e(SimpleMartyrForm::STEPS[$step]) ?></h2><form method="post" action="<?= e(url('admin',['tab'=>'martyrs'])) ?>" data-dirty-form data-simple-martyr><?= Security::field() ?><input type="hidden" name="action" value="protocol-save"><input type="hidden" name="simple_form" value="1"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="step" value="<?= $step ?>"><input type="hidden" name="revision" value="<?= e($old['revision']??$bundle['profile']['revision']) ?>">
<div class="fields"><?php foreach($defs as $key=>$def): $v=$values[$key]??null;$name='data['.$key.']';$fieldId='simple_'.$key;$military=in_array($key,['service_organization','service_subunit','service_position','service_place'],true); ?>
