<?php else: ?><section class="panel"><h2>وضعیت انتشار</h2><p class="notice">وضعیت فعلی: <?= e(Namira\AdminPublishing::label($bundle['profile']['status'])) ?> — نسخه <?= fa($bundle['profile']['revision']) ?></p><p>در این نسخه، ذخیره مدیر مجاز مستقیماً منتشر می‌شود؛ گردش کار بازبینی جداگانه فعال نیست.</p><form method="post"><?= Security::field() ?><input type="hidden" name="action" value="protocol-transition"><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="step" value="8"><input type="hidden" name="revision" value="<?= $bundle['profile']['revision'] ?>"><input type="hidden" name="status" value="published"><button class="primary">انتشار پرونده</button></form><p><a class="outline" href="<?= e(url('profile',['id'=>$id])) ?>" target="_blank" rel="noopener">پیش‌نمایش اطلاعات عمومی</a></p></section><?php endif ?>
<?php else: ?><p>ابتدا پرونده را با ثبت سریع ایجاد کنید.</p><?php endif ?>
